// === Tab: mySketch ===
let img;
let points = [];
// 原始代码参数
let isMobile = /iPhone|iPod|Android/i.test(navigator.userAgent);
let repel_radius;
let radius_;
let angle = 0;
const attractionBase = 0.01; // 原始吸引力
const attractionStrong = 0.15; // 图像状态下需要更强的吸引力
const damping = 0.9;
const repel_strength = 28;

// 采样步长：数字越大，粒子越少但性能越好。数字越小，图像越精细。
// 建议根据实际运行流畅度调整。
const sampleStep = 6; 

function preload() {
  // 【重要】请确保将你的参考图命名为 'shaman.png' 并上传到项目目录中
  img = loadImage('https://openprocessing.org/sketch/2851055/files/shaman.png');
}

function setup() {
  // 设置画布大小，尽量适应图片比例，或保持原样
  if (isMobile) {
    createCanvas(360, 500);
    radius_ = 140;
    repel_radius = 60;
  } else {
    createCanvas(800, 800);
    radius_ = 250;
    repel_radius = 90;
  }

  pixelDensity(1);
  noSmooth(); // 关闭平滑可能会提高一点性能并带来更锐利的像素感

  // 调整图片大小以适应画布，避免过大
  let scaleFactor = min(width / img.width, height / img.height) * 0.8;
  img.resize(img.width * scaleFactor, img.height * scaleFactor);

  // 图像采样初始化
  img.loadPixels();
  // 计算图像中心偏移量，让图像居中显示
  let offsetX = (width - img.width) / 2;
  let offsetY = (height - img.height) / 2;

  let indexCounter = 0;
  for (let y = 0; y < img.height; y += sampleStep) {
    for (let x = 0; x < img.width; x += sampleStep) {
      // 获取像素颜色索引
      let pixelIndex = (x + y * img.width) * 4;
      let r = img.pixels[pixelIndex];
      let g = img.pixels[pixelIndex + 1];
      let b = img.pixels[pixelIndex + 2];
      let a = img.pixels[pixelIndex + 3];

      // 如果像素不是透明的，则创建一个粒子
      if (a > 10) {
        // 计算该像素相对于画布中心的位置
        let targetX = x + offsetX - width / 2;
        let targetY = y + offsetY - height / 2;

        points.push({
          index: indexCounter, // 用于原始代码的旋转计算
          pos: createVector(random(-width, width), random(-height, height)), // 初始随机位置，让它们飞入
          vel: createVector(0, 0),
          imgTarget: createVector(targetX, targetY), // 图像形态下的目标位置
          col: color(r, g, b) // 粒子的颜色
        });
        indexCounter++;
      }
    }
  }
  console.log("Generated pixels: " + points.length);
}

function draw() {
  background(0);
  translate(width / 2, height / 2);

  // 1. 计算过渡进度 (0.0 到 1.0)
  // (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) 在最左边是 0 (图像形态)，在最右边是 1 (粒子球形态)
  let transition = constrain(map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0, 1), 0, 1);

  // 使用缓动函数让过渡更平滑 (可选)
  // transition = transition * transition * (3 - 2 * transition); // Smoothstep

  let mouse = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2);

  // 根据过渡进度调整物理参数
  // 当接近图像形态时(transition趋近0)，需要更强的吸引力来保持形状
  let currentAttraction = map(transition, 0, 1, attractionStrong, attractionBase);
  // 当接近图像形态时，鼠标斥力应该减弱或消失，否则图像会被冲散
  let currentRepelStr = map(transition, 0.2, 1, 0, repel_strength, true);

  for (let p of points) {
    let i = p.index;

    // --- 计算两个潜在目标点 ---

    // 目标 A: 图像上的原始位置
    let targetImage = p.imgTarget;

    // 目标 B: 旋转球体的位置 (原始代码逻辑)
    let sphereX = sin(i + angle) * sin(i * i) * radius_;
    let sphereY = cos(i * i) * radius_;
    let targetSphere = createVector(sphereX, sphereY);

    // --- 核心逻辑: 混合目标点 ---
    // 使用 lerp 在两个目标之间插值。transition 为 0 时完全是 targetImage，为 1 时完全是 targetSphere
    let finalTarget = p5.Vector.lerp(targetImage, targetSphere, transition);

    // --- 物理计算 ---

    // 1. 弹簧力指向最终混合目标
    let toHome = p5.Vector.sub(finalTarget, p.pos);
    // 距离越远拉力越大，乘以当前的吸引力系数
    let spring = toHome.mult(currentAttraction);
    p.vel.add(spring);

    // 2. 鼠标斥力 (仅当 transition 足够大时才生效)
    if (transition > 0.1) {
      let awayFromMouse = p5.Vector.sub(p.pos, mouse);
      let distSq = awayFromMouse.magSq();
      if (distSq > 0.1 && distSq < repel_radius * repel_radius) {
        let distance = sqrt(distSq);
        awayFromMouse.normalize();
        // 自然衰减
        let repelForce = currentRepelStr * (1 - distance / repel_radius);
        // 根据过渡进度进一步缩放斥力，确保在图像状态下斥力很小
        awayFromMouse.mult(repelForce * transition);
        p.vel.add(awayFromMouse);
      }
    }

    // 3. 阻尼和移动
    p.vel.mult(damping);
    p.pos.add(p.vel);

    // --- 渲染 ---
    // 使用采样到的颜色
    stroke(p.col);
    // 根据过渡状态调整点的大小 (可选：图像状态下点小一点更精细，粒子状态下大一点)
    let pointSize = map(transition, 0, 1, 1.5, 2.5);
    strokeWeight(pointSize);
    point(p.pos.x, p.pos.y);
  }

  // 只有在往粒子状态过渡时才开始旋转角度
  angle += 0.01 * transition;
}

